import type { InlineText } from '../types';

// Inline emphasis generated by the editor toolbar. Unmatched markers remain literal.
export function parseInlineMarkdown(text: string): InlineText[] {
  const pattern = /(\*\*\*|\*\*|\*)(?=\S)(.+?)\1/g;
  const runs: InlineText[] = [];
  let start = 0;
  for (const match of text.matchAll(pattern)) {
    const index = match.index!;
    if (index > start) runs.push({ text: text.slice(start, index) });
    const bold = match[1].length >= 2;
    const italics = match[1].length !== 2;
    for (const run of parseInlineMarkdown(match[2])) runs.push({ ...run, bold: bold || run.bold, italics: italics || run.italics });
    start = index + match[0].length;
  }
  if (start < text.length) runs.push({ text: text.slice(start) });
  return runs;
}

export function escapeHtml(text: string): string {
  return text.replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]!));
}

export function inlineMarkdownHtml(text: string): string {
  return parseInlineMarkdown(text).map(run => {
    let html = escapeHtml(run.text);
    if (run.bold) html = '<strong>' + html + '</strong>';
    if (run.italics) html = '<em>' + html + '</em>';
    return html;
  }).join('');
}
